public class SuppressedDemo {
    public static void processResources() throws Exception {
        try (AutoCloseableResource res1 = new AutoCloseableResource("Res1");
             AutoCloseableResource res2 = new AutoCloseableResource("Res2")) {
            throw new IllegalStateException("Primary business logic failure");
        } catch (Exception e) {
            System.err.println("Caught: " + e.getMessage());
            for (Throwable suppressed : e.getSuppressed()) {
                System.err.println("Suppressed: " + suppressed.getMessage());
            }
            throw e;
        }
    }
}
